#!/usr/bin/env node
/*
 * Block until there is something for the executor to act on, then print it and exit.
 * Used so the executor keeps working without a person relaying reviews (EXECUTOR_GUIDE §9).
 *
 *   node scripts/wait-for-review.cjs                 # watch all open PRs of this repo
 *   node scripts/wait-for-review.cjs --prs 47,48     # only these PRs
 *   node scripts/wait-for-review.cjs --max-minutes 25 --interval 60
 *
 * It reports, at most once each:
 *   - a new comment written by Claude (the body carries the "Generated by [Claude Code]" footer);
 *   - a CI check that failed on the current head of a watched PR;
 *   - a watched PR that was merged or closed.
 * Exit codes: 0 = something new was printed; 2 = nothing new before the time limit (run it again, or
 * finish the round); 1 = could not reach GitHub (see the message).
 *
 * GitHub access: the `gh` CLI if it is installed and logged in; otherwise a token in GH_TOKEN or GITHUB_TOKEN.
 * State (what was already reported) is kept in dist/review-wait-state.json, so a restart does not repeat items.
 */
'use strict';
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const REPO = process.env.REVIEW_REPO || 'Lmin2419/eta-background';
const FOOTER = 'Generated by [Claude Code]';
const args = process.argv.slice(2);
const opt = (name, fallback) => { const i = args.indexOf('--' + name); return i >= 0 && args[i + 1] ? args[i + 1] : fallback; };
const maxMinutes = Number(opt('max-minutes', '25'));
const intervalSeconds = Math.max(20, Number(opt('interval', '60')));
const onlyPrs = opt('prs', '').split(',').map(s => s.trim()).filter(Boolean).map(Number);
const statePath = path.join(__dirname, '..', 'dist', 'review-wait-state.json');

function loadState() {
  try { return JSON.parse(fs.readFileSync(statePath, 'utf8')); } catch (_) {
    // First run: look back 12 hours, so reviews posted while nobody was waiting are not missed.
    // Items already handled may show up once; check the PR and skip them.
    const since = opt('since', new Date(Date.now() - 12 * 3600 * 1000).toISOString());
    return { comments: [], failures: [], closed: [], since };
  }
}
function saveState(state) {
  fs.mkdirSync(path.dirname(statePath), { recursive: true });
  fs.writeFileSync(statePath, JSON.stringify(state, null, 1));
}

let useGh = null;
async function api(route) {
  if (useGh !== false) {
    try {
      const out = execFileSync('gh', ['api', '-H', 'Accept: application/vnd.github+json', route], { encoding: 'utf8', maxBuffer: 32 << 20, stdio: ['ignore', 'pipe', 'pipe'] });
      useGh = true;
      return JSON.parse(out);
    } catch (error) {
      // gh missing or not logged in: fall back to a token, but only if gh never worked in this run.
      if (useGh === true) throw new Error('gh api failed: ' + String(error.stderr || error.message).trim().split('\n')[0]);
      useGh = false;
    }
  }
  const token = process.env.GH_TOKEN || process.env.GITHUB_TOKEN;
  if (!token) throw new Error('Neither a logged-in `gh` CLI nor GH_TOKEN / GITHUB_TOKEN is available.');
  const res = await fetch('https://api.github.com/' + route.replace(/^\//, ''), {
    headers: { Authorization: 'Bearer ' + token, Accept: 'application/vnd.github+json', 'User-Agent': 'wait-for-review' },
  });
  if (!res.ok) throw new Error('GitHub API ' + res.status + ' for ' + route);
  return res.json();
}

async function watchedPrs() {
  if (onlyPrs.length) return onlyPrs;
  const open = await api(`repos/${REPO}/pulls?state=open&per_page=50`);
  return open.map(pr => pr.number);
}

async function poll(state) {
  const found = [];
  for (const number of await watchedPrs()) {
    const pr = await api(`repos/${REPO}/pulls/${number}`);
    if (pr.state !== 'open') {
      const key = String(number);
      if (!state.closed.includes(key)) { state.closed.push(key); found.push(`PR #${number} ${pr.merged ? '已合并' : '已关闭'}：${pr.title}`); }
      continue;
    }
    const comments = await api(`repos/${REPO}/issues/${number}/comments?since=${encodeURIComponent(state.since)}&per_page=100`);
    for (const c of comments) {
      if (!c.body || !c.body.includes(FOOTER) || state.comments.includes(c.id)) continue;
      state.comments.push(c.id);
      found.push(`PR #${number} 有 Claude 的新评论（${c.created_at}）：${c.html_url}\n\n${c.body.split('\n---')[0].trim()}`);
    }
    const runs = await api(`repos/${REPO}/commits/${pr.head.sha}/check-runs?per_page=100`);
    for (const run of runs.check_runs || []) {
      const key = pr.head.sha + ':' + run.name;
      if (run.status !== 'completed' || !['failure', 'timed_out', 'cancelled'].includes(run.conclusion) || state.failures.includes(key)) continue;
      state.failures.push(key);
      found.push(`PR #${number} 的 CI「${run.name}」失败（提交 ${pr.head.sha.slice(0, 7)}）：${run.html_url}`);
    }
  }
  return found;
}

(async () => {
  const state = loadState();
  const deadline = Date.now() + maxMinutes * 60 * 1000;
  console.log(`等待审查意见和 CI 结果（最长 ${maxMinutes} 分钟，每 ${intervalSeconds} 秒检查一次）…`);
  for (;;) {
    let found;
    try { found = await poll(state); } catch (error) { console.error('无法访问 GitHub：' + error.message); process.exit(1); }
    saveState(state);
    if (found.length) {
      console.log('\n' + found.join('\n\n========\n\n'));
      console.log('\n下一步：按 EXECUTOR_GUIDE 第 9 节处理以上内容，然后继续队列。');
      process.exit(0);
    }
    if (Date.now() + intervalSeconds * 1000 > deadline) {
      console.log('在时限内没有新的审查意见、CI 失败或合并。');
      process.exit(2);
    }
    await new Promise(resolve => setTimeout(resolve, intervalSeconds * 1000));
  }
})();
